    public RoomController(RoomRepository roomRepository) {
        this.roomRepository = roomRepository;
    }

    public void getRooms(Context ctx) {
        List<Room> rooms = roomRepository.findAll();

        List<Map<String, Object>> response = rooms.stream()
            .map(room -> {
