@Testcontainers
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class SystemIT {

    @Container
    private static final PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18-alpine")
        .withDatabaseName("test")
        .withUsername("test")
        .withPassword("test");

    private Javalin app;
